import socket, concurrent.futures, itertools, sys

ports = (80, 8080, 8000)
def check(target):
    ip, port = target
    try:
        s = socket.create_connection((ip, port), timeout=0.4)
        s.close()
        return target
    except OSError:
        return None

# 172.16.0.0/12 -> 172.16.x.x to 172.31.x.x. Skip our own /16 tail except .0.2 known.
targets = []
for b in range(16, 32):
    for c in range(0, 256):
        for d in (1, 2, 3, 4, 5, 10, 20, 50, 100, 200, 254):
            ip = f"172.{b}.{c}.{d}"
            if ip == "172.26.0.2":
                continue
            for p in ports:
                targets.append((ip, p))

print(f"{len(targets)} targets", flush=True)
found = []
with concurrent.futures.ThreadPoolExecutor(max_workers=500) as ex:
    for r in ex.map(check, targets, chunksize=50):
        if r:
            found.append(r)
            print("open:", r, flush=True)
print("done", found, flush=True)
